function imageFrom(src){if(!imageCache.has(src))imageCache.set(src,new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=src}));return imageCache.get(src)}
async function mapPreview(state,canvas){const width=state.map.columns*TILE_SIZE,height=state.map.rows*TILE_SIZE;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#111722';ctx.fillRect(0,0,width,height);if(state.map.background&&BACKGROUNDS.includes(state.map.background))try{ctx.drawImage(await imageFrom(`../../assets/tileset/PNG/Background/x32/${state.map.background}`),0,0,width,height)}catch{}for(const layer of state.layers||[]){if(layer.visible===false)continue;for(const p of layer.placements||[]){if(!SHEETS.includes(p.sheet))continue;try{const image=await imageFrom(`../../assets/tileset/PNG/${p.sheet}`);ctx.drawImage(image,p.sourceX*TILE_SIZE,p.sourceY*TILE_SIZE,p.width*TILE_SIZE,p.height*TILE_SIZE,p.x*TILE_SIZE,p.y*TILE_SIZE,p.width*TILE_SIZE,p.height*TILE_SIZE)}catch{}}}}
function spriteStyle(enemy){return `background-image:url('../../assets/enemy/Monsters%20Creatures%20Fantasy%202/${enemy.sprite}');background-size:auto 58px`}
function renderEnemyList(){$('#enemy-list').innerHTML=project.enemies.map(enemy=>`<button class="enemy-card ${enemy.type==='Boss'?'boss ':''}${enemy.id===selectedEnemyId?'active':''}" data-id="${enemy.id}"><span class="enemy-thumb"><i class="enemy-sprite" style="${spriteStyle(enemy)}"></i></span><span><strong>${enemy.name}</strong><span>${enemy.type} · Lv. ${enemy.level[0]}–${enemy.level[1]}</span></span><b>${project.spawns.filter(s=>s.enemyId===enemy.id).length}</b></button>`).join('');$$('.enemy-card').forEach(button=>button.onclick=()=>{selectedEnemyId=button.dataset.id;renderEnemyList();$('#placement-text').textContent=`${project.enemies.find(e=>e.id===selectedEnemyId).name} in einen Kartenabschnitt setzen`;renderInspector()})}
function createPortal(portal){const el=document.createElement('span');el.className='portal';Object.assign(el.style,{left:`${portal.x}px`,top:`${portal.y}px`});el.innerHTML=`<span class="portal-name">${portal.name}</span>`;return el}
