function createSection(section){const el=document.createElement('article');el.className='section';el.dataset.id=section.id;Object.assign(el.style,{left:`${section.x}px`,top:`${section.y}px`,width:`${mapWidth(section)}px`,height:`${mapHeight(section)}px`});const canvas=document.createElement('canvas'),label=document.createElement('span');label.className='section-label';label.textContent=section.name;el.append(canvas,label);mapPreview(section.mapState,canvas);if($('#show-portals').checked)for(const portal of project.world.portals.filter(p=>p.sectionId===section.id))el.append(createPortal(portal));if($('#show-npcs').checked)for(const npc of project.npcs.filter(n=>n.sectionId===section.id))el.append(createNpc(npc));for(const spawn of project.spawns.filter(s=>s.sectionId===section.id))el.append(createSpawn(spawn));el.onpointerdown=event=>sectionPointer(event,section,el);return el}
function renderWorld(){worldElement.querySelectorAll('.section').forEach(el=>el.remove());$('#world-name').textContent=project.world?.name||'Keine Welt geladen';$('#empty-world').hidden=Boolean(project.world?.sections.length);if(project.world)for(const section of project.world.sections)worldElement.append(createSection(section));$('#status-source').textContent=`Quelle: ${project.source}`;$('#status-count').textContent=`${project.spawns.filter(s=>s.kind==='spawner').length} Spawner · ${project.spawns.filter(s=>s.kind==='zone').length} Zonen · ${project.npcs.length} NPCs`}
function localPoint(event,el,section){const rect=el.getBoundingClientRect();return{x:Math.round((event.clientX-rect.left)/rect.width*mapWidth(section)),y:Math.round((event.clientY-rect.top)/rect.height*mapHeight(section))}}
function sectionPointer(event,section,el){if(tool!=='monster'&&tool!=='zone')return;event.stopPropagation();const point=localPoint(event,el,section),enemy=project.enemies.find(e=>e.id===selectedEnemyId);project.spawns.push({id:`spawn-${Date.now()}`,kind:tool==='zone'?'zone':'spawner',enemyId:enemy.id,sectionId:section.id,x:point.x,y:point.y,name:`${enemy.name}-${tool==='zone'?'Zone':'Spawner'}`,max:enemy.type==='Boss'?1:6,respawn:enemy.type==='Boss'?300:20,radius:tool==='zone'?160:64,behavior:'Gebiet bewachen',aggro:288,returns:true});selectedSpawnId=project.spawns.at(-1).id;setTool('select');markDirty();renderAll();toast(`${enemy.name} platziert`)}
