 $$('.appearance',root).forEach(button=>button.onclick=()=>{const a=APPEARANCES[Number(button.dataset.appearance)];enemy.sprite=a.sprite;enemy.frame=a.frame;markDirty();renderAll()});
 bindValue(root,'#enemy-name','input',el=>{enemy.name=el.value;renderEnemyList()});bindValue(root,'#enemy-type','change',el=>enemy.type=el.value);bindValue(root,'#level-min','change',el=>enemy.level[0]=Number(el.value));bindValue(root,'#level-max','change',el=>enemy.level[1]=Number(el.value));bindValue(root,'#enemy-hp','change',el=>enemy.hp=Number(el.value));bindValue(root,'#enemy-damage','change',el=>enemy.damage=Number(el.value));bindValue(root,'#enemy-armor','change',el=>enemy.armor=Number(el.value));bindValue(root,'#enemy-speed','change',el=>enemy.speed=Number(el.value));bindValue(root,'#enemy-xp','change',el=>enemy.xp=Number(el.value));bindValue(root,'#enemy-gold','change',el=>{enemy.gold=el.value.split(/[–-]/).map(Number)});
 $$('[data-drop]',root).forEach(input=>input.onchange=()=>{enemy.drops[Number(input.dataset.drop)].chance=Number(input.value);markDirty()});$$('[data-remove-drop]',root).forEach(button=>button.onclick=()=>{enemy.drops.splice(Number(button.dataset.removeDrop),1);markDirty();renderEnemyPanel()});$('#add-drop').onclick=()=>{enemy.drops.push({name:`Neuer Drop ${enemy.drops.length+1}`,chance:10});markDirty();renderEnemyPanel()}
