function ensureAnimation(enemyId){if(!project.animations[enemyId])project.animations[enemyId]={sequences:[{name:'Idle',count:3,done:0},{name:'Start Walking',count:2,done:0},{name:'Walking',count:5,done:0},{name:'Stop Walking',count:2,done:0},{name:'Attack 1',count:4,done:0}],frames:{}};return project.animations[enemyId]}
function renderAnimationPanel(){const root=$('#tab-animation'),enemy=project.enemies.find(e=>e.id===selectedEnemyId),animation=ensureAnimation(enemy.id),done=animation.sequences.reduce((s,a)=>s+a.done,0),total=animation.sequences.reduce((s,a)=>s+a.count,0);root.innerHTML=`<div class="animation-summary"><div><strong>${done} von ${total} Bildern fertig</strong><span>${animation.sequences.length} Sequenzen</span></div><progress max="${total}" value="${done}"></progress></div>${animation.sequences.map(s=>`<div class="animation-card"><strong>${s.name}</strong><span>${s.done}/${s.count} Bilder</span></div>`).join('')}<button id="open-animation" class="primary wide">Design Studio öffnen</button><button id="add-attack" class="wide">+ Weitere Attacke</button>`;$('#open-animation').onclick=openAnimationDialog;$('#add-attack').onclick=()=>{const attacks=animation.sequences.filter(s=>s.name.startsWith('Attack')).length+1;animation.sequences.push({name:`Attack ${attacks}`,count:4,done:0});markDirty();renderAnimationPanel()}}
function renderInspector(){renderSpawnPanel();renderEnemyPanel();renderAnimationPanel();const spawn=project.spawns.find(s=>s.id===selectedSpawnId),enemy=project.enemies.find(e=>e.id===selectedEnemyId);$('#inspector-title').textContent=spawn?.name||enemy?.name||'Nichts ausgewählt'}
function renderAll(){renderEnemyList();renderWorld();renderInspector()}
function setTool(next){tool=next;$$('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('#status-tool').textContent={select:'Auswahl',monster:'Monster platzieren',zone:'Monsterzone',erase:'Löschen',pan:'Hand'}[tool];$('#placement-banner').hidden=!['monster','zone'].includes(tool);if(!$('#placement-banner').hidden)$('#placement-text').textContent=`${project.enemies.find(e=>e.id===selectedEnemyId).name} in einen Kartenabschnitt setzen`}
function readSources(){const list=[];try{const saved=JSON.parse(localStorage.getItem(QUEST_STORAGE_KEY)||'null');if(saved?.project?.world)list.push({label:'Prototyp 04 · NPCs & Quests',meta:`${saved.project.world.sections.length} Abschnitte · ${saved.project.npcs?.length||0} NPCs`,world:saved.project.world,npcs:saved.project.npcs||[]})}catch{}try{const saved=JSON.parse(localStorage.getItem(WORLD_STORAGE_KEY)||'null');if(saved?.world)list.push({label:'Prototyp 03 · Welt-Builder',meta:`${saved.world.sections.length} Abschnitte · ${saved.world.portals.length} Portale`,world:saved.world,npcs:[]})}catch{}try{const maps=JSON.parse(localStorage.getItem(MAP_LIBRARY_KEY)||'[]');for(const map of maps)if(map?.state?.map)list.push({label:`Prototyp 02 · ${map.name}`,meta:`${map.state.map.columns}×${map.state.map.rows} Tiles`,world:{version:2,name:map.name,sections:[{id:`map-${map.id}`,sourceMapId:map.id,name:map.name,x:3500,y:2200,mapState:map.state}],portals:[],spawn:null},npcs:[]})}catch{}return list}
function openWorldDialog(){const sources=readSources();$('#world-sources').innerHTML=sources.length?sources.map((source,i)=>`<article class="source-card"><strong>${source.label}</strong><span>${source.meta}</span><button data-source="${i}" class="primary">Übernehmen</button></article>`).join(''):'<div class="empty-list">Noch keine Daten gefunden. Speichere zuerst eine Map in Prototyp 02 oder eine Welt in Prototyp 03.</div>';$$('[data-source]').forEach(button=>button.onclick=()=>{const source=sources[Number(button.dataset.source)];project.world=clone(source.world);project.npcs=clone(source.npcs);project.source=source.label;$('#world-dialog').close();renderAll();requestAnimationFrame(centerWorld);toast('Welt übernommen')});$('#world-dialog').showModal()}
function centerWorld(){if(!project.world?.sections.length)return;const left=Math.min(...project.world.sections.map(s=>s.x)),right=Math.max(...project.world.sections.map(s=>s.x+mapWidth(s))),top=Math.min(...project.world.sections.map(s=>s.y)),bottom=Math.max(...project.world.sections.map(s=>s.y+mapHeight(s)));viewport.scrollTo({left:(left+right)*zoom/2-viewport.clientWidth/2,top:(top+bottom)*zoom/2-viewport.clientHeight/2})}
let animationSequence=0,animationFrame=0,paintTool='draw',painting=false;
const pixelCanvas=$('#pixel-canvas'),pixelContext=pixelCanvas.getContext('2d'),GRID=16;
function basePixels(){const pixels=Array.from({length:GRID},()=>Array(GRID).fill(null));['................','................','.....GGGG.......','...GGGGGGGG.....','..GGGGGGGGGG....','.GGGGGGGGGGGG...','.GGGLLGGLLGGG...','.GGGDDGGDDGGG...','.GGGGGGGGGGGG...','.GGGGGGGGGGGG...','.GGGGGGGGGGGG...','GGGGGGGGGGGGGG..','GGGGGGGGGGGGGG..','GGGGGGGGGGGGGG..','.GGGG....GGGG...','................'].forEach((row,y)=>[...row].forEach((cell,x)=>pixels[y][x]=cell==='G'?'#88b95a':cell==='L'?'#d7e684':cell==='D'?'#344532':null));return pixels}
function frameKey(){return `${animationSequence}:${animationFrame}`}
function currentPixels(){const animation=ensureAnimation(selectedEnemyId);if(!animation.frames[frameKey()])animation.frames[frameKey()]=basePixels();return animation.frames[frameKey()]}
function drawPixels(){const size=pixelCanvas.width/GRID,pixels=currentPixels();pixelContext.fillStyle='#cbd1c7';pixelContext.fillRect(0,0,pixelCanvas.width,pixelCanvas.height);if($('#show-ghost').checked){pixelContext.globalAlpha=.13;pixelContext.fillStyle='#a05f59';pixelContext.beginPath();pixelContext.ellipse(256+(animationFrame%3-1)*18,286+(animationFrame%2)*12,155,130,0,0,Math.PI*2);pixelContext.fill();pixelContext.globalAlpha=1}for(let y=0;y<GRID;y++)for(let x=0;x<GRID;x++)if(pixels[y][x]){pixelContext.fillStyle=pixels[y][x];pixelContext.fillRect(x*size,y*size,size,size)}pixelContext.strokeStyle='#5e685f33';for(let i=0;i<=GRID;i++){pixelContext.beginPath();pixelContext.moveTo(i*size,0);pixelContext.lineTo(i*size,512);pixelContext.stroke();pixelContext.beginPath();pixelContext.moveTo(0,i*size);pixelContext.lineTo(512,i*size);pixelContext.stroke()}}
function renderAnimationDialog(){const animation=ensureAnimation(selectedEnemyId),sequence=animation.sequences[animationSequence];$('#animation-kicker').textContent=`${sequence.name} · Bild ${animationFrame+1} von ${sequence.count}`;$('#animation-title').textContent=`${sequence.name} ${animationFrame+1}`;$('#sequence-list').innerHTML=animation.sequences.map((s,i)=>`<button class="sequence-group ${i===animationSequence?'active':''}" data-sequence="${i}"><span>${s.name}</span><b>${s.done}/${s.count}</b></button>`).join('');$$('[data-sequence]',$('#sequence-list')).forEach(button=>button.onclick=()=>{animationSequence=Number(button.dataset.sequence);animationFrame=0;renderAnimationDialog()});$('#ghost-preview').style.transform=`translateY(${animationFrame%2?8:0}px) scale(${1+(animationFrame%2)*.06},${1-(animationFrame%2)*.04})`;drawPixels()}
function openAnimationDialog(){animationSequence=0;animationFrame=0;renderAnimationDialog();$('#animation-dialog').showModal()}
function moveAnimation(delta,complete=false){const animation=ensureAnimation(selectedEnemyId),sequence=animation.sequences[animationSequence];if(complete)sequence.done=Math.max(sequence.done,animationFrame+1);if(delta>0&&animationFrame===sequence.count-1){if(animationSequence<animation.sequences.length-1){animationSequence++;animationFrame=0;toast(`${sequence.name} abgeschlossen`)}else toast('Alle Bilder abgeschlossen')}else animationFrame=Math.max(0,Math.min(sequence.count-1,animationFrame+delta));markDirty();renderAnimationDialog();renderAnimationPanel()}
function paint(event,erase=false){const rect=pixelCanvas.getBoundingClientRect(),x=Math.floor((event.clientX-rect.left)/rect.width*GRID),y=Math.floor((event.clientY-rect.top)/rect.height*GRID);if(x<0||y<0||x>=GRID||y>=GRID)return;currentPixels()[y][x]=erase||paintTool==='erase'?null:$('#paint-color').value;markDirty();drawPixels()}
pixelCanvas.onpointerdown=event=>{painting=true;pixelCanvas.setPointerCapture(event.pointerId);paint(event,event.button===2)};pixelCanvas.onpointermove=event=>{if(painting)paint(event,event.buttons===2)};pixelCanvas.onpointerup=()=>painting=false;pixelCanvas.oncontextmenu=event=>event.preventDefault();$$('.paint-tool').forEach(button=>button.onclick=()=>{$$('.paint-tool').forEach(b=>b.classList.remove('active'));button.classList.add('active');paintTool=button.dataset.paint});$('#show-ghost').onchange=drawPixels;$('#previous-frame').onclick=()=>moveAnimation(-1);$('#skip-frame').onclick=()=>moveAnimation(1);$('#complete-frame').onclick=()=>moveAnimation(1,true);$('.close-animation').onclick=()=>$('#animation-dialog').close();
function saveProject(){localStorage.setItem(PROJECT_STORAGE_KEY,JSON.stringify({updatedAt:Date.now(),project}));$('#save-state').textContent='Lokal gespeichert';toast('Monster-Projekt gespeichert')}
function loadProject(){try{const saved=JSON.parse(localStorage.getItem(PROJECT_STORAGE_KEY)||'null');if(!saved?.project)throw new Error();project=clone(saved.project);project.animations||={};project.npcs||=[];selectedEnemyId=project.enemies[0]?.id||null;selectedSpawnId=null;renderAll();requestAnimationFrame(centerWorld);toast('Monster-Projekt geladen')}catch{toast('Noch kein Monster-Projekt gespeichert')}}
function exportProject(){const blob=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${(project.world?.name||'idlekin').replace(/[^a-z0-9äöüß-]+/gi,'-').toLowerCase()}-monster.json`;link.click();URL.revokeObjectURL(url);toast('Projekt exportiert')}
function playProject(){if(!project.world?.sections.length)return toast('Lade zuerst eine Welt');localStorage.setItem(PLAYTEST_KEY,JSON.stringify({source:'05',label:project.world.name||'Monster-Test',returnUrl:'../05-monster-boss-editor/',project:clone(project)}));location.href='../01-side-view-movement/'}
$$('.tool').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#zoom').onchange=()=>{zoom=Number($('#zoom').value);worldElement.style.zoom=zoom};$('#load-world').onclick=$('#empty-load').onclick=openWorldDialog;$('#load-project').onclick=loadProject;$('#play-project').onclick=playProject;$('#save-project').onclick=saveProject;$('#export-project').onclick=exportProject;$('.close-dialog').onclick=()=>$('#world-dialog').close();$('#center-world').onclick=centerWorld;$('#cancel-placement').onclick=()=>setTool('select');$('#show-portals').onchange=renderWorld;$('#show-npcs').onchange=renderWorld;
$('#add-enemy').onclick=()=>{const enemy={...clone(ENEMIES[0]),id:`enemy-${Date.now()}`,name:`Neuer Gegner ${project.enemies.length+1}`,drops:[]};project.enemies.push(enemy);selectedEnemyId=enemy.id;selectedSpawnId=null;markDirty();renderAll();$('.tab[data-tab="enemy"]').click();toast('Neuer Gegner angelegt')};
$$('.tab').forEach(button=>button.onclick=()=>{$$('.tab').forEach(b=>b.classList.remove('active'));button.classList.add('active');$$('.tab-panel').forEach(panel=>panel.hidden=true);$(`#tab-${button.dataset.tab}`).hidden=false});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('#animation-dialog').open)$('#animation-dialog').close();else setTool('select')}if(!event.ctrlKey&&!event.metaKey){const key=event.key.toLowerCase();if({v:'select',m:'monster',z:'zone',e:'erase',h:'pan'}[key])setTool({v:'select',m:'monster',z:'zone',e:'erase',h:'pan'}[key])}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveProject()}});
worldElement.style.zoom=zoom;
try{const saved=JSON.parse(localStorage.getItem(PROJECT_STORAGE_KEY)||'null');if(saved?.project){project=clone(saved.project);project.animations||={};project.npcs||=[];selectedEnemyId=project.enemies[0]?.id||null}else{const source=readSources()[0];if(source){project.world=clone(source.world);project.npcs=clone(source.npcs);project.source=source.label}}}catch{}
renderAll();setTimeout(centerWorld,100);
